(sh) => {
    sh.uniforms.uSssC = { value: rimC }; sh.uniforms.uSssK = m.userData.sssK;
    if (glowMap) { sh.uniforms.uGlowMap = { value: glowMap }; sh.uniforms.uGlow = m.userData.glow; sh.uniforms.uGlowC = { value: new THREE.Color(glowColor) }; }
    sh.fragmentShader = sh.fragmentShader.replace('#include <common>', '#include <common>\nuniform vec3 uSssC; uniform float uSssK;' + (glowMap ? '\nuniform sampler2D uGlowMap; uniform float uGlow; uniform vec3 uGlowC;' : ''))
      .replace('#include <emissivemap_fragment>', `#include <emissivemap_fragment>
        float skRim = pow(1.0 - abs(dot(normalize(vViewPosition), normal)), 2.6);
        totalEmissiveRadiance += uSssC * skRim * uSssK * (0.6 + 0.6 * diffuseColor.r);
        ${glowMap ? '#ifdef USE_MAP\n totalEmissiveRadiance += uGlowC * texture2D(uGlowMap, vMapUv).r * uGlow;\n#endif' : ''}`);
  }

